def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my = [h[0] for h in history]
    op = [h[1] for h in history]

    op_c = op.count('C')
    op_d = n - op_c
    my_d = my.count('D')

    last_my = my[-1]
    last_op = op[-1]

    last3 = op[-3:]
    last5 = op[-5:]
    r3d = last3.count('D')
    r5d = last5.count('D')

    op_D_run = 0
    if last_op == 'D':
        i = n - 1
        while i >= 0 and op[i] == 'D':
            op_D_run += 1
            i -= 1

    op_C_run = 0
    if last_op == 'C':
        i = n - 1
        while i >= 0 and op[i] == 'C':
            op_C_run += 1
            i -= 1

    my_D_run = 0
    if last_my == 'D':
        i = n - 1
        while i >= 0 and my[i] == 'D':
            my_D_run += 1
            i -= 1

    c_attempts = 0
    if op_D_run > 0:
        start = n - op_D_run
        for i in range(start, n):
            if my[i] == 'C':
                c_attempts += 1

    before = n - op_D_run
    prior_coop = op_c / before if before > 0 else 0.0

    start_tol = n - 6
    if start_tol < 1:
        start_tol = 1

    recent_tol = 0
    recent_pun = 0
    for i in range(start_tol, n):
        if my[i - 1] == 'D':
            if op[i] == 'C':
                recent_tol += 1
            else:
                recent_pun += 1

    if last_op == 'D':
        if op_D_run == 1 and n >= 3:
            if my[-1] == 'C' and my[-2] == 'D' and op[-2] == 'C':
                if op_c >= op_d - 1 and r5d <= 3:
                    return 'C'

        if op_D_run >= 2 and before >= 3 and prior_coop >= 0.65 and op_D_run <= 8 and c_attempts < 3:
            if not (n > 30 and op_d * 3 > n):
                return 'C'

        if n >= 10 and op_d >= n - 1:
            return 'D'
        if n >= 20 and op_d >= n - 2:
            return 'D'
        if op_d * 2 >= n:
            return 'D'
        if r3d >= 2:
            return 'D'
        return 'D'

    if last_op == 'C' and last_my == 'D':
        if recent_tol >= 2 and recent_pun == 0 and op_C_run >= 8:
            if op_c * 3 >= n * 2 and my_D_run < 8:
                return 'D'
        return 'C'

    if last_op == 'C':
        if op_C_run >= 3 and recent_tol >= 1 and recent_pun == 0:
            if op_c * 3 >= n * 2 and my_d * 2 <= n + 10:
                threshold = 0.30
                if op_C_run >= 8:
                    threshold = 0.70
                elif op_C_run >= 5:
                    threshold = 0.50
                elif op_C_run >= 4:
                    threshold = 0.40
                if rng.random() < threshold:
                    return 'D'

        if n >= 90 and op_C_run >= 2 and recent_pun == 0:
            if op_c * 3 >= n * 2 and rng.random() < 0.25:
                return 'D'

    if op_d <= max(1, n // 8):
        return 'C'

    if op_d <= max(2, n // 6):
        if r3d <= 1:
            return 'C'

    if r3d >= 2:
        return 'D'

    if op_d * 2 >= n:
        return 'D'

    return 'C'
